import path from "node:path";
import { fileURLToPath } from "node:url";
import { AutoTokenizer } from "@huggingface/transformers";
//#region src/index.ts
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const tokenizerDir = path.resolve(__dirname, "../tokenizer");
let tokenizerPromise = null;
function getTokenizer() {
	if (!tokenizerPromise) tokenizerPromise = AutoTokenizer.from_pretrained(tokenizerDir);
	return tokenizerPromise;
}
/**
* Calculate the token count of text
*
* @example
* ```ts
* const count = await countTokens('Hello!')
* // 2
* ```
*/
async function countTokens(text) {
	return (await getTokenizer()).encode(text).length;
}
/**
* Encode text into an array of token IDs
*
* @param text Text to encode
* @param options Encoding options, forwarded to the underlying transformers.js tokenizer
*/
async function encode(text, options) {
	return (await getTokenizer()).encode(text, options);
}
//#endregion
export { countTokens, encode };
